		"cc.note.privacy": "Your text is processed entirely in your browser. Nothing is sent to any server.",
		"faq.cc.title": "Frequently Asked Questions",
		"faq.cc.1.q": "How does the character counter work?",
		"faq.cc.1.a": "Paste or type into the box — every stat updates instantly as you type, no button needed.",
		"faq.cc.2.q": "Are spaces counted as characters?",
		"faq.cc.2.a": "**Characters** counts everything including spaces. **No spaces** strips all whitespace first.",
		"faq.cc.3.q": "How are words counted for Japanese and Chinese text?",
		"faq.cc.3.a": "The tool uses the browser's built-in **Intl.Segmenter** API, which applies proper linguistic word-break rules for each language — including Japanese, Chinese, Korean, and Thai — rather than simply splitting on spaces.",
		"faq.cc.4.q": "What is the byte count?",
		"faq.cc.4.a": "The byte count shows the UTF-8 encoded size. ASCII characters use 1 byte. Full-width CJK characters typically use 3 bytes each. This matters for APIs, databases, and platforms with byte limits.",
		"faq.cc.5.q": "What are full-width and half-width characters?",
		"faq.cc.5.a": "Full-width characters are CJK ideographs, kana, and full-width Latin/punctuation — each typically occupies 2 columns in a monospace grid. Half-width characters are standard ASCII and half-width katakana — 1 column each.",
		"faq.cc.6.q": "What is the Manuscript (400) count?",
		"faq.cc.6.a": "Japanese manuscript paper (原稿用紙) has 400 character cells per sheet. This stat shows how many sheets your text fills, which is useful for academic papers, novels, and formal writing in Japan.",
		"faq.cc.7.q": "How is reading time estimated?",
		"faq.cc.7.a": "Reading speed is calculated per script: CJK text uses ~500 characters/minute; Latin text uses ~238 words/minute. Mixed texts blend both rates proportionally.",
		"faq.cc.8.q": "Is my text stored or sent anywhere?",
		"faq.cc.8.a": "No. All processing runs locally in your browser. Your text is never uploaded or stored on any server.",
