		"related.snsCharacterLimit.title": "SNS Character Limit",
		"related.snsCharacterLimit.desc": "Check your text fits X, Instagram, YouTube and more.",
		"wc.meta.title": "Word Counter – Free Online Word Count Tool | Squishyfile",
		"wc.meta.desc": "Free online word counter. Count words, characters, sentences, paragraphs and reading time in real time. No upload, no account needed.",
		"wc.hero.title": "Word Counter",
		"wc.hero.sub": "Paste or type your text — words, characters, and reading time counted instantly.",
