		"mc.hero.sub": "Paste your text — see characters, words, and 400-character manuscript pages at a glance.",
		"scl.meta.title": "SNS Character Limit Checker – X, Instagram, YouTube & More | Squishyfile",
		"scl.meta.desc": "Check your text fits character limits for X, Instagram, YouTube, Meta descriptions and more. Real-time counter, no upload needed.",
		"scl.hero.title": "SNS Character Limit",
		"scl.hero.sub": "Paste your text — check it fits limits for X, Instagram, YouTube, and more.",
		"faq.wc.title": "Frequently Asked Questions",
		"faq.wc.1.q": "How does the word counter work?",
		"faq.wc.1.a": "Paste or type text into the box. The word count updates in real time — no button to press.",
		"faq.wc.2.q": "How are words counted?",
		"faq.wc.2.a": "The tool uses the browser's built-in **Intl.Segmenter** API, which applies proper linguistic word-break rules for each language — including Japanese, Chinese, Korean, and Thai — rather than simply splitting on spaces.",
		"faq.wc.3.q": "How is reading time estimated?",
		"faq.wc.3.a": "Reading speed is calculated per script: CJK text at ~500 characters/minute; Latin text at ~238 words/minute. Mixed texts blend both rates proportionally.",
		"faq.wc.4.q": "Does it work for Japanese and Chinese?",
		"faq.wc.4.a": "Yes. Japanese and Chinese have no spaces between words. **Intl.Segmenter** uses dictionary-based rules to find word boundaries correctly in both languages.",
		"faq.wc.5.q": "Are spaces counted in the character total?",
		"faq.wc.5.a": "**Characters** counts everything including spaces. **No spaces** strips whitespace before counting.",
		"faq.wc.6.q": "Is there a word limit?",
		"faq.wc.6.a": "No limit is enforced. Very large texts may slow down older devices.",
		"faq.wc.7.q": "Is my text sent to a server?",
		"faq.wc.7.a": "No. All processing runs locally in your browser. Your text is never uploaded or stored.",
		"faq.wc.8.q": "Can I use this on mobile?",
		"faq.wc.8.a": "Yes. The tool works in modern mobile browsers on iPhone and Android without any app install.",
		"faq.mc.title": "Frequently Asked Questions",
		"faq.mc.1.q": "What is a manuscript page (原稿用紙)?",
		"faq.mc.1.a": "Japanese manuscript paper (原稿用紙, genkou youshi) has a grid of 400 character cells — typically 20 columns × 20 rows. It is the standard format for academic papers, novels, and formal writing in Japan.",
		"faq.mc.2.q": "How is the page count calculated?",
		"faq.mc.2.a": "The page count is your character count, excluding spaces, divided by 400 and shown to one decimal place. For example, 1,200 characters = 3.0 pages.",
		"faq.mc.3.q": "Does it count spaces?",
		"faq.mc.3.a": "Spaces and line breaks are excluded from the manuscript page count, following the standard convention for 原稿用紙.",
		"faq.mc.4.q": "How are full-width and half-width characters handled?",
		"faq.mc.4.a": "Both full-width and half-width characters are each counted as 1 character cell in the 400-character grid, matching the standard 原稿用紙 convention.",
		"faq.mc.5.q": "How are words counted?",
		"faq.mc.5.a": "The tool uses **Intl.Segmenter** with proper linguistic rules, so Japanese and Chinese words are counted correctly without relying on spaces.",
		"faq.mc.6.q": "Is this accurate for formal submissions?",
		"faq.mc.6.a": "This tool gives a reliable estimate based on the standard 400-character-per-sheet convention. Always verify the specific requirements of your institution or publisher.",
		"faq.mc.7.q": "Is my text sent to a server?",
		"faq.mc.7.a": "No. All processing runs in your browser. Nothing is uploaded.",
		"faq.mc.8.q": "Can I use it on mobile?",
		"faq.mc.8.a": "Yes. The tool works in modern mobile browsers on iPhone and Android.",
		"faq.scl.title": "Frequently Asked Questions",
		"faq.scl.1.q": "What platforms are supported?",
		"faq.scl.1.a": "The character count works for any platform. Common limits for reference: X (Twitter) 280, Instagram caption 2,200, YouTube title 100, Meta description 160.",
		"faq.scl.2.q": "How is the character count calculated?",
		"faq.scl.2.a": "Characters are counted by Unicode code points, which is how most platforms measure length. Emojis may count differently depending on the platform.",
		"faq.scl.3.q": "Does X (Twitter) count characters differently?",
		"faq.scl.3.a": "X counts most characters as 1, but URLs are shortened to a fixed length regardless of the original URL length. This tool counts raw characters, so adjust if your text includes URLs.",
		"faq.scl.4.q": "Why does Instagram allow 2,200 characters but only show part of the caption?",
		"faq.scl.4.a": "Instagram often truncates captions in the feed after the opening text and shows a “more” link. The full limit applies to the caption itself.",
		"faq.scl.5.q": "What is a meta description character limit?",
		"faq.scl.5.a": "Search results often display only part of a meta description. Keeping it concise helps avoid truncation.",
		"faq.scl.6.q": "Is my text sent to a server?",
