		'faq.video.6.q': 'Discord用に8MB以下にできますか？',
		'faq.video.6.a': '動画の長さや内容によりますが、ターゲットファイルサイズを8MBに指定して圧縮できます。長い動画や動きの激しい動画では、画質を大きく下げる必要がある場合があります。',

