		'faq.pdf.11.a': 'メールに添付したいPDF、Webフォームに提出する履歴書や申請書、スキャンした書類、画像や写真が多いPDF、プレゼン資料をPDF化したファイルなどに向いています。',

		'faq.pdf.12.q': 'PDFの容量があまり減らないのはなぜですか？',
