		'faq.1.a': 'Sim, com toda a certeza! Squishyfile processa seus vídeos localmente diretamente no seu navegador. Seus arquivos nunca são enviados para nenhum servidor em nuvem, garantindo privacidade e segurança 100%.',
		'faq.2.q': 'Existe limite de tamanho de arquivo para comprimir vídeo?',
		'faq.2.a': 'Não aplicamos limites de servidor pois tudo roda no seu dispositivo. Para desempenho estável na memória do navegador, recomendamos manter os arquivos abaixo de 2 GB.',
