		"faq.cc.title": "Perguntas frequentes",
		"faq.cc.1.q": "Como o contador de caracteres funciona?",
		"faq.cc.1.a": "Cole ou digite o texto na caixa. Todas as métricas são atualizadas em tempo real, sem precisar clicar em nenhum botão.",
		"faq.cc.2.q": "Espaços contam como caracteres?",
		"faq.cc.2.a": "**Caracteres** conta tudo, incluindo espaços. **Sem espaços** remove todos os espaços em branco antes de contar.",
		"faq.cc.3.q": "Como as palavras são contadas em japonês e chinês?",
		"faq.cc.3.a": "A ferramenta usa a API **Intl.Segmenter** do navegador, que aplica regras linguísticas de segmentação para cada idioma, incluindo japonês, chinês, coreano e tailandês.",
		"faq.cc.4.q": "O que é contagem de bytes?",
		"faq.cc.4.a": "A contagem de bytes mostra o tamanho do texto em UTF-8. Caracteres ASCII usam 1 byte; caracteres CJK de largura cheia geralmente usam 3 bytes. Isso ajuda em limites de APIs, bancos de dados e plataformas.",
		"faq.cc.5.q": "O que são caracteres de largura cheia e meia largura?",
		"faq.cc.5.a": "Caracteres de largura cheia incluem ideogramas CJK, kana e pontuação larga, ocupando geralmente 2 colunas em fonte monoespaçada. Meia largura inclui ASCII e alguns kana, ocupando 1 coluna.",
		"faq.cc.6.q": "O que é Manuscrito (400)?",
		"faq.cc.6.a": "O papel de manuscrito japonês, 原稿用紙, tem 400 células por folha. Esta métrica mostra quantas folhas seu texto preencheria.",
		"faq.cc.7.q": "Como o tempo de leitura é estimado?",
