		"faq.wc.3.q": "Como o tempo de leitura é estimado?",
		"faq.wc.3.a": "Textos CJK usam cerca de 500 caracteres/minuto; textos latinos usam cerca de 238 palavras/minuto. Textos mistos são calculados proporcionalmente.",
		"faq.wc.4.q": "Funciona para japonês e chinês?",
		"faq.wc.4.a": "Sim. Japonês e chinês não usam espaços entre todas as palavras; **Intl.Segmenter** aplica regras adequadas para encontrar os limites das palavras.",
		"faq.wc.5.q": "Espaços entram no total de caracteres?",
