		"faq.mc.title": "Perguntas frequentes",
		"faq.mc.1.q": "O que é uma página de manuscrito japonês?",
		"faq.mc.1.a": "O papel de manuscrito japonês, 原稿用紙, tem uma grade de 400 células, normalmente 20 colunas × 20 linhas. É usado em redações, romances e textos formais no Japão.",
		"faq.mc.2.q": "Como a quantidade de páginas é calculada?",
		"faq.mc.2.a": "A contagem de páginas é o número de caracteres sem espaços dividido por 400, exibido com uma casa decimal. Por exemplo, 1.200 caracteres = 3,0 páginas.",
		"faq.mc.3.q": "Espaços são contados?",
		"faq.mc.3.a": "Espaços e quebras de linha são excluídos da contagem de páginas, seguindo a convenção comum do 原稿用紙.",
		"faq.mc.4.q": "Como caracteres de largura cheia e meia largura são tratados?",
		"faq.mc.4.a": "Tanto caracteres de largura cheia quanto de meia largura contam como 1 célula na grade de 400 caracteres.",
		"faq.mc.5.q": "Como as palavras são contadas?",
		"faq.mc.5.a": "A ferramenta usa **Intl.Segmenter** com regras linguísticas, então japonês, chinês e outros idiomas podem ser contados sem depender apenas de espaços.",
		"faq.mc.6.q": "É preciso para submissões formais?",
		"faq.mc.6.a": "A ferramenta fornece uma estimativa confiável com base na convenção de 400 caracteres por folha. Sempre confirme regras específicas da instituição ou editora.",
		"faq.mc.7.q": "Meu texto é enviado?",
		"faq.mc.7.a": "Não. Tudo roda no navegador. Nada é enviado.",
		"faq.mc.8.q": "Funciona no celular?",
		"faq.mc.8.a": "Sim. Funciona em navegadores modernos no iPhone e Android.",
		"faq.scl.title": "Perguntas frequentes",
		"faq.scl.1.q": "Quais plataformas são suportadas?",
		"faq.scl.1.a": "A contagem de caracteres serve para qualquer plataforma. Exemplos comuns: X, legenda do Instagram, título do YouTube e Meta description.",
		"faq.scl.2.q": "Como a contagem de caracteres é calculada?",
		"faq.scl.2.a": "Caracteres são contados por pontos de código Unicode, método próximo ao usado por muitas plataformas. Emojis e URLs podem variar conforme a plataforma.",
		"faq.scl.3.q": "O X conta caracteres de forma diferente?",
		"faq.scl.3.a": "O X conta a maioria dos caracteres como 1, mas URLs costumam ter comprimento fixo. Esta ferramenta mostra a contagem bruta; ajuste se o texto tiver URLs.",
		"faq.scl.4.q": "Por que o Instagram permite 2.200 caracteres, mas corta a legenda?",
		"faq.scl.4.a": "No feed, o Instagram costuma mostrar apenas o começo da legenda e um link “mais”. O limite completo se aplica à legenda inteira.",
		"faq.scl.5.q": "O que é limite de caracteres de Meta description?",
		"faq.scl.5.a": "Resultados de busca geralmente exibem apenas parte da descrição. Manter o texto conciso reduz a chance de truncamento.",
		"faq.scl.6.q": "Meu texto é enviado para servidor?",
		"faq.scl.6.a": "Não. Tudo roda localmente no navegador. Seu texto nunca é enviado.",
		"faq.scl.7.q": "Suporta português, japonês e outros idiomas?",
